308	    ///
309	    /// Returns `None` if the path is already at the root.
310	    pub fn parent(&self) -> Option<Self> {
311	        let mut segments = self.0.clone();
312	        if !segments.pop() {
313	            return None;
314	        }
315	        Some(Self(segments))
